<template>
	<div class="User page">
		<div class="box">
			<div class="cell margin-top-10">
				<div class="col-4"></div>
				<!-- <div class="col-16"><img class="title" src="@/assets/img/user.png"></div> -->
				<div class="col-16">
					<div class="title">用户中心</div>
				</div>
				<div class="col-4 text-right" @click="go('back')">
					<img class="close" @click="$bridge.closeWebView()" src="@/assets/img/close.png">
				</div>
			</div>
			<!-- 			<div class="cell text-center">
				<div class="input font-color-grey" v-if="userInfo">{{userInfo.phone?userInfo.phone:userInfo.nickname}}
				</div>
			</div> -->
			<div class="text-center font-color-grey" v-if="userInfo">{{userInfo.phone?userInfo.phone:userInfo.nickname}}
			</div>
			<div class="padding-0-20">
				<div class="padding-bottom-20 bg-lightgrey border-radius-10">
					<div class="cell text-center padding-top-0">
						<div class="col-8">
							<img class="user-center-icon" @click="goBind" src="@/assets/img/bind-icon.png">
						</div>
						<div class="col-8" @click="goUpdatePassword">
							<img class="user-center-icon" src="@/assets/img/password-icon.png">
						</div>
						<div class="col-8">
							<img class="user-center-icon" @click="goAuth" src="@/assets/img/auth-icon.png">
						</div>
					</div>
					<div class="cell text-center">
						<div class="col-8">
							<img class="user-center-icon" @click="go('/service')" src="@/assets/img/service-icon.png">
						</div>

						<div class="col-8">
							<img class="user-center-icon" @click="switchUser" src="@/assets/img/switch-icon.png">
						</div>

						<div class="col-8">
							<img class="user-center-icon" @click="go('/logoff')" src="@/assets/img/logoff-icon.png">
						</div>
					</div>
				</div>
			</div>
			<div class="padding-20" v-if="initData">
				<!-- <div class="col-24 text-right font-color-grey margin-bottom-10">渠道号：{{initData.yofiChannelId}}</div>
				<div class="col-24 text-right font-color-grey margin-bottom-10">版本 Version：{{initData.yofiSdkVersion}}
				</div> -->
				<div class="col-24 text-right font-color-grey margin-bottom-10 text-center">
					渠道号：{{initData.yofiChannelId}} 版本 Version：{{initData.yofiSdkVersion}}&{{sdkVersion}}
				</div>
			</div>
			<br />
			<br />
			<br />
		</div>
	</div>
</template>

<script>
	import {
		ref
	} from 'vue'
	export default {
		name: 'User',
		setup() {
			return {
				sdkVersion: ref('')
			}
		},
		created() {
			this.sdkVersion = process.env.VUE_APP_VERSION
		},
		methods: {
			goBind() {
				if (this.userInfo && this.userInfo.phone) {
					this.go('/phoneVerify')
				} else {
					this.go('/bind')
				}
			},
			goAuth() {
				if (this.userInfo && this.userInfo.isAuthentication) {
					return this.$toast.show('已实名认证')
				} else {
					return this.go('/auth')
				}

			},
			goUpdatePassword() {
				if (!this.userInfo) {
					this.$toast.show('请先登录')
				} else if (!this.userInfo.phone) {
					this.go('/bind')
				} else {
					this.go('/updatePassword')
				}
			},
			switchUser() {
				if (!this.userInfo || !this.userInfo.accessToken) {
					this.$confirm.show({
						text: '您还未登录，前往登录？',
						titleImg: require('@/assets/img/switch.png'),
						submitCallBack: async () => {
							this.$router.push('/login')
						}
					})
				} else {
					this.$confirm.show({
						text: '确认退出当前账号？',
						titleImg: require('@/assets/img/switch.png'),
						submitCallBack: async () => {
							let res = await this.$store.dispatch('login/loginOut')
							if (this.$check.ok(res)) {
								this.$toast.show('退出成功')
								if (this.userInfo && this.userInfo.userType != 0) { //游客类型
									this.$store.commit('SET_USER_INFO', null)
								}
								this.$store.commit('SET_LOGIN_WITHOUT_ACCOUNT_LOCAL', false)
								this.$bridge.logout(res[0].data.data)
								this.$router.push('/login')
							}
						}
					})
				}
			}
		}
	}
</script>
<style scoped>
	.User {
		display: table-cell;
		text-align: center;
		vertical-align: middle;
	}


	@media (min-width: 420px) {
		.close {
			height: 30px;
			line-height: 30px;
			position: relative;
			top: -4px
		}
	}

	@media (max-width: 420px) {
		.padding-top-0 {
			padding-top: 0;
		}

		.close {
			height: 30px;
			line-height: 30px;
			position: relative;
			top: 4px
		}
	}
</style>
